struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *index_key = NULL;
    struct key *new_key = NULL;
    struct user_struct *current_user = NULL;
    int ret = 0;

    if (!dest_keyring || key_validate(dest_keyring) < 0) {
        return ERR_PTR(-EINVAL);
    }

    index_key = keyring_search(ctx, NULL, NULL);
    if (IS_ERR(index_key)) {
        return index_key;
    }

    current_user = get_current_user();
    if (!current_user) {
        return ERR_PTR(-ENOMEM);
    }

    new_key = key_alloc(index_key->type, callout_info, callout_len,
                        current_user, flags, 0, 0, NULL);
    if (IS_ERR(new_key)) {
        put_user(current_user);
        key_put(index_key);
        return new_key;
    }

    ret = key_instantiate_and_link(new_key, callout_info, callout_len,
                                   index_key, aux);
    if (ret < 0) {
        key_put(new_key);
        put_user(current_user);
        key_put(index_key);
        return ERR_PTR(ret);
    }

    ret = keyring_link(dest_keyring, new_key);
    if (ret < 0) {
        key_put(new_key);
        put_user(current_user);
        key_put(index_key);
        return ERR_PTR(ret);
    }

    key_put(index_key);
    put_user(current_user);
    return new_key;
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct key *keyring = NULL;
    struct user_struct *user = NULL;
    int ret = 0;

    if (!dest_keyring || !callout_info || !ctx)
        return ERR_PTR(-EINVAL);

    keyring = keyring_search(ctx, NULL, NULL);
    if (IS_ERR(keyring))
        return keyring;

    user = get_current_user();
    if (!user) {
        ret = -ENOMEM;
        goto error;
    }

    key = alloc_key();
    if (!key) {
        ret = -ENOMEM;
        goto error;
    }

    ret = key_instantiate(key, callout_info, callout_len, aux);
    if (ret < 0)
        goto error;

    key->flags |= flags;

    ret = link_key_to_keyring(key, dest_keyring);
    if (ret < 0)
        goto error;

    return key;

error:
    if (key)
        free_key(key);
    if (keyring && !IS_ERR(keyring))
        key_put(keyring);
    if (user)
        free_user(user);
    return ERR_PTR(ret);
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct key *index_key = NULL;
    struct key *target_keyring = NULL;
    struct key *new_key = NULL;
    struct user_struct *user = NULL;
    int ret = 0;

    if (!ctx || !callout_info || !dest_keyring) {
        return ERR_PTR(-EINVAL);
    }

    index_key = lookup_key_type(ctx->type);
    if (IS_ERR(index_key)) {
        return index_key;
    }

    target_keyring = keyring_search(ctx, index_key, NULL);
    if (IS_ERR(target_keyring)) {
        key_put(index_key);
        return target_keyring;
    }

    user = get_current_user();
    if (!user) {
        key_put(index_key);
        key_put(target_keyring);
        return ERR_PTR(-ENOMEM);
    }

    new_key = key_alloc(&key_type_user, callout_info, callout_len, user, 0, flags, 0);
    if (IS_ERR(new_key)) {
        ret = PTR_ERR(new_key);
        goto error;
    }

    ret = key_instantiate_and_link(new_key, (void *)callout_info, callout_len, dest_keyring, aux);
    if (ret < 0) {
        key_revoke(new_key);
        key_put(new_key);
        goto error;
    }

    key_put(index_key);
    key_put(target_keyring);
    put_user(user);
    return new_key;

error:
    key_put(index_key);
    key_put(target_keyring);
    put_user(user);
    return ERR_PTR(ret);
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct user_struct *user;
    int ret;

    /* Retrieve current user */
    user = get_current_user();
    if (!user)
        return ERR_PTR(-ENOMEM);

    /* Allocate a new key */
    key = key_alloc(&key_type_user, callout_info, callout_len, user,
                    flags, NULL, NULL);
    if (IS_ERR(key))
        return key;

    /* Set key data if necessary */
    ret = key_instantiate(key, aux, callout_len);
    if (ret < 0) {
        key_put(key);
        return ERR_PTR(ret);
    }

    /* Link the key to the destination keyring */
    ret = key_link(dest_keyring, key);
    if (ret < 0) {
        key_put(key);
        return ERR_PTR(ret);
    }

    return key;
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct key *index_key = NULL;
    struct user_struct *user = NULL;
    int ret = 0;

    /* Retrieve the index key type from the context */
    index_key = keyring_search(ctx, NULL, NULL);
    if (IS_ERR(index_key)) {
        return index_key;
    }

    /* Retrieve the current user */
    user = get_current_user();
    if (!user) {
        ret = -ENOMEM;
        goto error;
    }

    /* Allocate a new key */
    key = key_alloc(index_key, callout_len + 1, &user->uid, NULL, NULL, flags, NULL);
    if (IS_ERR(key)) {
        ret = PTR_ERR(key);
        goto error;
    }

    /* Copy callout information into the new key */
    ret = key->type->v2->instantiate(key, callout_info, callout_len, aux);
    if (ret < 0) {
        goto error;
    }

    /* Link the new key to the destination keyring */
    ret = key_link(dest_keyring, key);
    if (ret < 0) {
        goto error;
    }

    return key;

error:
    if (key) {
        key_revoke(key);
        key_put(key);
    }
    put_user(user);
    key_put(index_key);
    return ERR_PTR(ret);
}
